/**
 * Finnish performance instructions for the rest of the exercise library.
 *
 * The first 245 entries (the lifts the ready programs prescribe, and a few the
 * swap pools reach) live in exerciseInstructions.ts. This file carries every
 * other library entry (708 of them, 3018 steps), so that a Finnish
 * reader browsing the library meets Finnish steps and not the English of the
 * public database.
 *
 * KEPT HERE AND NOT IN THE LIBRARY. `npm run exercise:sync` rewrites the
 * generated English library, so nothing Finnish can live in it. The English
 * exercise name is the key, exactly as in exerciseInstructions.ts and
 * `EXERCISE_NAME_FI`, and a test keeps the two paired (same step count, no
 * orphaned key, no entry left in English).
 *
 * LOADED ON FIRST USE. This is about 0.4 MB of text and the app evaluates
 * every module before the first render, on Hermes without a JIT.
 * exerciseInstructions.ts therefore requires this file only when a Finnish
 * reader opens an exercise the first table does not cover, and never for an
 * English reader. Do not import it from anywhere else.
 *
 * STYLE. The same as the first table: short imperative gym Finnish, step for
 * step with the English, kg and cm for pounds and inches, the breathing
 * narration and the repeated "this will be your starting position" turned
 * into plain coaching, and no promise of an outcome. Product-style names
 * (Smith, EZ-tanko, Bosu, Atlas-kivi, yoke) stay as they are. "Wind Sprints"
 * describes a hanging knee raise because the upstream entry does; the steps
 * follow the entry, not the name.
 */
