    'Kierrä kyynärvartta ulospäin niin, että käsipaino nousee puoliympyrää pitkin, ja pidä olkavarren ja kyynärvarren välinen 90 asteen kulma. Jatka kiertoa, kunnes kyynärvarsi on kohtisuorassa lattiaan nähden ja osoittaa kattoa kohti. Pysähdy sekunniksi.',
    'Palaa hitaasti alkuasentoon.',
    'Toista ohjelman mukainen määrä toistoja ja vaihda sitten toiseen käteen.',
