    'Ojenna kädet sivuille kyynärpäät hieman koukussa. Pidä koukistus samana koko liikkeen ajan. Kädet ovat lattian suuntaiset. Tämä on alkuasento.',
    'Nosta kädet puoliympyrässä suoraan eteesi vetämällä taljoja yhteen, kunnes kädet kohtaavat ylhäällä. Purista rintaa liikkeen aikana ja pysähdy ylhäällä sekunniksi. Ylhäällä kädet ovat kohtisuorassa vartaloon ja lattiaan nähden ja koskettavat toisiaan rinnan yläpuolella.',
