    'Käännä molemmat käsipainot ylös yhtä aikaa, kunnes hauikset ovat täysin supistuneet. Älä heilauta käsiä tai käytä vauhtia, pidä liike koko ajan hallittuna. Pysähdy ylhäällä sekunniksi.',
    'Palaa hitaasti alkuasentoon.',
    'Toista ohjelman mukainen määrä toistoja.',
