    'Tartu tangon takaosaan vasemmalla kädellä. Kämmen on neutraalissa otteessa ja osoittaa oikealle. Varmista, että ote on tasainen tangolla. Vartalo on tangon keskellä ja etäisyys vartalosta oikeaan käteen (edessä) on sama kuin vasempaan käteen (takana).',
