    'Aloita täysin ojennetusta asennosta ja laske tanko kuin tekisit ojentajapunnerruksen maaten. Kun olet puolivälissä, anna tangon rullata noin 2,5 cm taaksepäin viemällä olkavarret kohti jalkoja, kunnes ne ovat kohtisuorassa vartaloon nähden. Pidä kyynärpäiden koukistus samana viedessäsi olkavarsia eteen.',
