    'Astu pois telineeltä ja ota hartioiden levyinen asento, varpaat hieman ulospäin. Pidä katse ylhäällä, sillä alas katsominen vie tasapainon. Pidä selkä suorana ja polvet hieman koukussa, älä koskaan lukossa. Tämä on alkuasento.',
    'Nosta kantapäitä ojentamalla nilkat niin korkealle kuin pystyt ja supista pohkeita. Pidä polvet koko ajan paikallaan, älä koukista niitä (alkuasennon pientä koukistusta lukuun ottamatta). Pysähdy sekunniksi ennen kuin laskeudut.',
    'Laske kantapäät hitaasti alas koukistamalla nilkat, kunnes pohkeet venyvät.',
    'Nosta nyt varpaita supistamalla pohkeiden etupuolella olevia säärilihaksia.',
