    'Tämä on alkuasento.',
    'Pidä olkavarsi lähellä päätä (kyynärpää sisäänpäin) ja kohtisuorassa lattiaan nähden ja laske paino puoliympyrää pitkin pään taakse, kunnes kyynärvarsi koskettaa hauista. Olkavarsi pysyy paikallaan ja vain kyynärvarsi liikkuu.',
